import re
from .coco_section_generic import YAMLBasedSectionGeneric


class SectionEpc(YAMLBasedSectionGeneric):
    def __init__(self, section_name='EPC'):
        super().__init__(section_name)

    def _prepare_section_content(self, enb_config, epc_config, *args, **kwargs):
        mme_list = [elements for elements in epc_config if re.match(r'^mme', elements)]
        return {
            'SGW': self._prepare_sgw_subsection_content(epc_config),
            'PGW': self._prepare_pgw_subsection_content(epc_config),
            'MME': self._prepare_mme_subsection_content(epc_config, mme_list),
            'MME_POOL_AREA': self._prepare_mme_pool_area_subsection_content(epc_config, enb_config, mme_list)
        }

    @staticmethod
    def _prepare_sgw_subsection_content(epc):
        sgw_subsection_content = []
        sgw_list = [elements for elements in epc if re.match(r'^sgw', elements)]
        for sgw in sgw_list:
            sgw_id = re.search(r'\d+', sgw).group(0)
            sgw_subsection_content.append({'id': int(sgw_id),
                                           'type': 'simulated',
                                           })
        return sgw_subsection_content

    @staticmethod
    def _prepare_pgw_subsection_content(epc):
        pgw_subsection_content = []
        pgw_list = [elements for elements in epc if re.match(r'^pgw', elements)]
        for pgw in pgw_list:
            pgw_id = re.search(r'\d+', pgw).group(0)
            pgw_subsection_content.append({
                'id': int(pgw_id),
                'type': 'simulated',
                'apn': epc[f'pgw{pgw_id}']['apn']
            })
        return pgw_subsection_content

    @staticmethod
    def _prepare_mme_subsection_content(epc, mme_list):
        mme_subsection_content = []

        for mme in mme_list:
            mme_id = re.search(r'\d+', mme).group(0)
            mmegi = epc[f'mme{mme_id}']['mmegi']
            mme_subsection_content.append({'id': int(mme_id),
                                           'pool': [f'{int(mme_id)}:{mmegi}'],
                                           's1': epc[f'mme{mme_id}']['s1_addr'],
                                           'type': 'simulated',
                                           })
        return mme_subsection_content

    @staticmethod
    def _prepare_mme_pool_area_subsection_content(epc, enb, mme_list):
        mme_pool_area_subsection_content = []

        for mme in mme_list:
            mme_id = re.search(r'\d+', mme).group(0)
            plmn_list = ','.join([
                '{}:{}'.format(*element.split('-'))
                for element in epc[f'mme{int(mme_id)}']['supported_plmn']
            ])
            tac_list = {cell_ent['tac'] for enb in enb.values() for cell_ent in enb['cells'].values()}

            mme_pool_area_subsection_content.append({
                'id': int(mme_id),
                'plmn': f'{plmn_list}',
                'mmegi': int(epc[f'mme{int(mme_id)}']['mmegi']),
                'tac_list': ','.join(tac_list),
            })
        return mme_pool_area_subsection_content
